:root {
  --accent: hsl(100 78% 70%);
  --text: #e9eef7;
}
.button { color: rgb(12 18 28); background: var(--accent); }

body {
  font-family: system-ui, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
}
h1 { font-weight: 800; letter-spacing: -0.03em; }

.hidden { display: none; }
.inline { display: inline; }
.row { display: flex; }
.grid { display: grid; }

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 1rem;
}

.container { position: relative; }
.badge {
  position: absolute;
  inset-block-start: .5rem;
  inset-inline-end: .5rem;
}
.sticky { position: sticky; top: 0; }

.cards { display: grid; grid-template-columns: repeat(3, 1fr); }
@media (max-width: 760px) {
  .cards { grid-template-columns: 1fr; }
}

:root {
  --surface: #121b29;
  --text: #edf3fc;
  --accent: #a6f078;
}
.card { color: var(--text); background: var(--surface); }

a:hover { color: #9b4c20; }
button:focus-visible { outline: 3px solid orange; }
li::marker { color: green; }
.card::before { content: "✦"; }

.button {
  background: #a6f078;
  transition: background-color 160ms ease, transform 160ms ease;
}
.button:hover { transform: translateY(-2px); }

@keyframes appear {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.notice { animation: appear 240ms ease-out both; }

.panel {
  max-height: 20rem;
  overflow: auto;
}
.title {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.card {
  border: 1px solid #2b394d;
  border-radius: 14px;
  box-shadow: 0 12px 32px rgb(0 0 0 / 18%);
}

.content { width: min(100% - 2rem, 72rem); margin-inline: auto; }
.avatar { width: 3rem; aspect-ratio: 1; border-radius: 50%; }
.media { max-width: 100%; height: auto; }

